import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  random,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {noise3D} from '@remotion/noise';

/* ═══════════════════════════════════════════════════════════ FONT */

const FONT_CSS = `
@font-face{font-family:'MxMono42';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;font-display:block;}
@font-face{font-family:'MxTitle42';src:url(data:font/woff2;base64,) format('woff2');font-weight:700;font-style:normal;font-display:block;}
`;

let fontsPromise: Promise<unknown> | null = null;
const ensureFonts = () => {
  if (fontsPromise) return fontsPromise;
  const st = document.createElement('style');
  st.textContent = FONT_CSS;
  document.head.appendChild(st);
  fontsPromise = Promise.all([
    (document as any).fonts.load("400 24px 'MxMono42'"),
    (document as any).fonts.load("700 24px 'MxTitle42'"),
  ]).catch(() => null);
  return fontsPromise;
};

const useEmbeddedFonts = () => {
  const [handle] = useState(() => delayRender('fonts-motion42'));
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      setReady(true);
      continueRender(handle);
    };
    const to = setTimeout(finish, 2500);
    ensureFonts().then(finish, finish);
    return () => clearTimeout(to);
  }, [handle]);
  return ready;
};

